package com.classvoice.controller;
import com.classvoice.dao.UserDAO; import com.classvoice.model.User; import com.classvoice.util.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/register") public class RegisterServlet extends HttpServlet {protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{String name=WebUtil.trim(r.getParameter("name")),email=WebUtil.trim(r.getParameter("email")).toLowerCase(),password=r.getParameter("password"),role=WebUtil.trim(r.getParameter("role"));String err=null;if(name.length()<2||name.length()>100)err="Name must be between 2 and 100 characters.";else if(!email.matches("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$"))err="Enter a valid email address.";else if(password==null||password.length()<8||password.length()>100)err="Password must be 8-100 characters.";else if(!role.equals("student")&&!role.equals("teacher"))err="Choose a valid role.";try{UserDAO dao=new UserDAO();if(err==null&&dao.findByEmail(email)!=null)err="An account with this email already exists.";if(err!=null){r.setAttribute("error",err);r.setAttribute("name",name);r.setAttribute("email",email);r.setAttribute("role",role);r.getRequestDispatcher("/register.jsp").forward(r,p);return;}User u=new User();u.setName(name);u.setEmail(email);u.setPassword(PasswordUtil.hash(password));u.setRole(role);dao.create(u);p.sendRedirect(r.getContextPath()+"/login.jsp?registered=1");}catch(Exception e){throw new ServletException(e);}}}
